CREATE TABLE IF NOT EXISTS industry_templates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(100) NOT NULL, industry VARCHAR(50) NOT NULL, description TEXT, preset_skills JSONB, preset_fields JSONB, preset_workflows JSONB, preset_roles JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_it_industry ON industry_templates(industry);
CREATE TABLE IF NOT EXISTS enterprise_skill_matrix (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id UUID NOT NULL, skill_name VARCHAR(100) NOT NULL, is_enabled BOOLEAN DEFAULT true, custom_opening_message TEXT, custom_params JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_esm_enterprise ON enterprise_skill_matrix(enterprise_id); CREATE UNIQUE INDEX IF NOT EXISTS idx_esm_enterprise_skill ON enterprise_skill_matrix(enterprise_id, skill_name);
CREATE TABLE IF NOT EXISTS claude_md_templates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), operator_id UUID NOT NULL, name VARCHAR(100) NOT NULL, content TEXT NOT NULL, is_default BOOLEAN DEFAULT false, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_cmt_operator ON claude_md_templates(operator_id);
ALTER TABLE knowledge_docs ADD COLUMN IF NOT EXISTS version INT DEFAULT 1;
ALTER TABLE knowledge_docs ADD COLUMN IF NOT EXISTS parent_version_id UUID;
ALTER TABLE knowledge_docs ADD COLUMN IF NOT EXISTS visibility VARCHAR(20) DEFAULT 'public';
ALTER TABLE knowledge_docs ADD COLUMN IF NOT EXISTS allowed_department_ids JSONB;
